/// Verifies that a buffer of bytes contains a `SFE`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_sfe_unchecked`.
#[inline]
pub fn root_as_sfe(buf: &[u8]) -> Result<SFE<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<SFE>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `SFE` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_sfe_unchecked`.
#[inline]
pub fn size_prefixed_root_as_sfe(buf: &[u8]) -> Result<SFE<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<SFE>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `SFE` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_sfe_unchecked`.
#[inline]
pub fn root_as_sfe_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<SFE<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<SFE<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `SFE` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_sfe_unchecked`.
